-- Source archive verified against official-image PYTHON_SHA256; installed build/byte selectors constrain applicability.
CREATE TABLE cpython_embedded_term (version TEXT NOT NULL, name TEXT NOT NULL, archive_sha256 TEXT NOT NULL, source_path TEXT NOT NULL, source_sha256 TEXT NOT NULL, notice_path TEXT NOT NULL, notice_sha256 TEXT NOT NULL, installed_selector TEXT NOT NULL, mode TEXT NOT NULL, build_key TEXT NOT NULL, build_indicator TEXT NOT NULL, expression TEXT NOT NULL, PRIMARY KEY(version,name));
